std::string Environment(const char* name) {
  const char* value = std::getenv(name);
  return value == nullptr ? std::string() : std::string(value);
}

bool ParseBool(const std::string& value, bool fallback) {
  if (value.empty()) return fallback;
  std::string normalized = value;
  std::transform(normalized.begin(), normalized.end(), normalized.begin(),
                 [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
  if (normalized == "1" || normalized == "true" || normalized == "yes" ||
      normalized == "on") return true;
  if (normalized == "0" || normalized == "false" || normalized == "no" ||
      normalized == "off") return false;
  throw std::runtime_error("Invalid boolean environment value: " + value);
}

int ParsePort(const std::string& value, int fallback) {
  if (value.empty()) return fallback;
  const int port = std::stoi(value);
  if (port < 1 || port > 65535) throw std::runtime_error("Port is out of range.");
  return port;
}

std::filesystem::path DefaultRuntimeDirectory() {
#ifdef _WIN32
  const std::string local_app_data = Environment("LOCALAPPDATA");
  if (!local_app_data.empty()) {
    return std::filesystem::path(local_app_data) / "SkinMapLocal";
  }
#endif
  return std::filesystem::temp_directory_path() / "SkinMapLocal";
}

}  // namespace

Config Config::FromEnvironment(const std::filesystem::path& root) {
  Config config;
  config.project_root = std::filesystem::absolute(root);
  config.runtime_dir = DefaultRuntimeDirectory();
  if (const auto value = Environment("SKINMAP_RUNTIME_DIR"); !value.empty()) {
    config.runtime_dir = std::filesystem::absolute(value);
  }
  config.jobs_dir = config.runtime_dir / "jobs";
  config.host = Environment("SKINMAP_HOST").empty()
                    ? config.host
                    : Environment("SKINMAP_HOST");
  config.port = ParsePort(Environment("SKINMAP_PORT"), config.port);

  config.face_cascade_path =
      config.project_root / "assets/models/haarcascade_frontalface_alt2.xml";
  config.skin_calibration_path =
      config.project_root / "assets/calibration/skin_map_v2.json";
  config.skin_device_profiles_path =
      config.project_root / "assets/calibration/mobile_device_profiles_v3.json";
  config.skin_residual_model_path =
      config.project_root / "assets/models/skin_map_residual_v3.onnx";

  if (const auto value = Environment("SKINMAP_CALIBRATION"); !value.empty()) {
    config.skin_calibration_path = std::filesystem::absolute(value);
  }
  if (const auto value = Environment("SKINMAP_DEVICE_PROFILES"); !value.empty()) {
    config.skin_device_profiles_path = std::filesystem::absolute(value);
  }
  if (const auto value = Environment("SKINMAP_RESIDUAL_MODEL"); !value.empty()) {
    config.skin_residual_model_path = std::filesystem::absolute(value);
  }

  config.vendor_skin_engine_root = config.project_root.parent_path() / "Engine";
  if (const auto value = Environment("SKINMAP_VENDOR_ENGINE_ROOT"); !value.empty()) {
    config.vendor_skin_engine_root = std::filesystem::absolute(value);
#ifdef _WIN32
  } else if (!std::filesystem::is_regular_file(
                 config.vendor_skin_engine_root / "XingerEngine.exe")) {
    const std::string local_app_data = Environment("LOCALAPPDATA");
    const auto ascii_engine = std::filesystem::path(local_app_data) /
                              "SkinMapLocal" / "VendorEngine";
    if (!local_app_data.empty() &&
        std::filesystem::is_regular_file(ascii_engine / "XingerEngine.exe")) {
      config.vendor_skin_engine_root = ascii_engine;
    }
#endif
  }
  config.vendor_skin_exe_path = config.vendor_skin_engine_root / "XingerEngine.exe";
  config.vendor_skin_host = Environment("SKINMAP_VENDOR_HOST").empty()
                                ? config.vendor_skin_host
                                : Environment("SKINMAP_VENDOR_HOST");
  config.vendor_skin_port =
      ParsePort(Environment("SKINMAP_VENDOR_PORT"), config.vendor_skin_port);
  config.vendor_skin_autostart =
      ParseBool(Environment("SKINMAP_VENDOR_AUTOSTART"), true);
  if (const auto value = Environment("SKINMAP_VENDOR_STARTUP_SECONDS");
      !value.empty()) {
    config.vendor_skin_startup_seconds = std::max(1, std::stoi(value));
  }
  if (const auto value = Environment("SKINMAP_VENDOR_TOTAL_SECONDS");
      !value.empty()) {
    config.vendor_skin_total_seconds = std::max(1, std::stoi(value));
  }
  return config;
}

void Config::EnsureDirectories() const {
  std::filesystem::create_directories(runtime_dir);
  std::filesystem::create_directories(jobs_dir);
}

