server.Post("/v1/skin-maps/rgb",
            [&](const httplib::Request& request, httplib::Response& response) {
  Guard(response, [&] {
    if (!request.has_file("image")) {
      throw Error("RGB_IMAGE_REQUIRED",
                  "Upload one front image field named 'image'.", 422);
    }
    const auto& file = request.get_file_value("image");
    const std::string extension = LowerExtension(file.filename);
    if (extension != ".jpg" && extension != ".jpeg" && extension != ".png") {
      throw Error("UNSUPPORTED_IMAGE_TYPE", "Only JPG and PNG images are accepted.",
                  415, {{"filename", file.filename}});
    }
    const auto record = jobs.Create("skin_rgb");
    const std::string job_id = record.at("job_id").get<std::string>();
    try {
      const auto input = jobs.JobDirectory(job_id) / "input";
      SaveUpload(file, input / ("image" + extension), config.max_image_bytes);
      std::string profile = "generic";
      if (request.has_file("device_profile")) {
        profile = request.get_file_value("device_profile").content;
      } else if (request.has_param("device_profile")) {
        profile = request.get_param_value("device_profile");
      }
      SaveDeviceProfile(profile, input / "device_profile.txt");
      jobs.Submit(job_id);
    } catch (...) {
      jobs.Delete(job_id);
      throw;
    }
    Json(response, 202, record);
  });
});

server.Post("/v1/skin-maps/instrument",
            [&](const httplib::Request& request, httplib::Response& response) {
  Guard(response, [&] {
    const std::vector<std::pair<std::string, std::string>> required_fields = {
        {"rgb_front", "RGB_M.jpg"},   {"rgb_left", "RGB_L.jpg"},
        {"rgb_right", "RGB_R.jpg"},  {"cp_front", "CP_M.jpg"},
        {"cp_left", "CP_L.jpg"},     {"cp_right", "CP_R.jpg"},
        {"uv365_front", "365_M.jpg"}, {"uv365_left", "365_L.jpg"},
        {"uv365_right", "365_R.jpg"}};
    const std::vector<std::pair<std::string, std::string>> optional_fields = {
        {"pp_front", "PP_M.jpg"}, {"pp_left", "PP_L.jpg"},
        {"pp_right", "PP_R.jpg"}};
    std::vector<std::string> missing;
    for (const auto& [field, _] : required_fields) {
      if (!request.has_file(field)) missing.push_back(field);
    }
    if (!missing.empty()) {
      throw Error("MISSING_MODALITY", "Upload all RGB, CP and 365 views.", 422,
                  {{"missing_fields", missing}});
    }
    const std::set<std::string> allowed = {".jpg", ".jpeg", ".png"};
    for (const auto& [field, _] : required_fields) {
      const auto& file = request.get_file_value(field);
      if (!allowed.contains(LowerExtension(file.filename))) {
        throw Error("UNSUPPORTED_IMAGE_TYPE", "Only JPG and PNG images are accepted.",
                    415, {{"filename", file.filename}});
      }
    }
    for (const auto& [field, _] : optional_fields) {
      if (!request.has_file(field)) continue;
      const auto& file = request.get_file_value(field);
      if (!allowed.contains(LowerExtension(file.filename))) {
        throw Error("UNSUPPORTED_IMAGE_TYPE", "Only JPG and PNG images are accepted.",
                    415, {{"filename", file.filename}});
      }
    }
    const auto record = jobs.Create("skin_instrument");
    const std::string job_id = record.at("job_id").get<std::string>();
    try {
      const auto input = jobs.JobDirectory(job_id) / "input";
      for (const auto& [field, filename] : required_fields) {
        SaveUpload(request.get_file_value(field), input / filename,
                   config.max_image_bytes);
      }
      for (const auto& [field, filename] : optional_fields) {
        if (request.has_file(field)) {
          SaveUpload(request.get_file_value(field), input / filename,
                     config.max_image_bytes);
        }
      }
      jobs.Submit(job_id);
    } catch (...) {
      jobs.Delete(job_id);
      throw;
    }
    Json(response, 202, record);
  });
});

