std::string Sha256File(const std::filesystem::path& path) {
#ifdef _WIN32
  std::ifstream stream(path, std::ios::binary);
  if (!stream) throw Error("SKIN_CALIBRATION_MISSING", "Skin calibration file is missing.", 503);
  const std::vector<unsigned char> data((std::istreambuf_iterator<char>(stream)),
                                        std::istreambuf_iterator<char>());
  BCRYPT_ALG_HANDLE algorithm = nullptr;
  BCRYPT_HASH_HANDLE hash = nullptr;
  DWORD object_bytes = 0;
  DWORD hash_bytes = 0;
  DWORD result_bytes = 0;
  if (BCryptOpenAlgorithmProvider(&algorithm, BCRYPT_SHA256_ALGORITHM, nullptr, 0) < 0 ||
      BCryptGetProperty(algorithm, BCRYPT_OBJECT_LENGTH,
                        reinterpret_cast<PUCHAR>(&object_bytes), sizeof(object_bytes),
                        &result_bytes, 0) < 0 ||
      BCryptGetProperty(algorithm, BCRYPT_HASH_LENGTH,
                        reinterpret_cast<PUCHAR>(&hash_bytes), sizeof(hash_bytes),
                        &result_bytes, 0) < 0) {
    if (algorithm) BCryptCloseAlgorithmProvider(algorithm, 0);
    throw Error("SHA256_UNAVAILABLE", "Windows SHA-256 provider is unavailable.", 500);
  }
  std::vector<unsigned char> object(object_bytes);
  std::vector<unsigned char> digest(hash_bytes);
  const bool failed =
      BCryptCreateHash(algorithm, &hash, object.data(), object_bytes, nullptr, 0, 0) < 0 ||
      BCryptHashData(hash, const_cast<PUCHAR>(data.data()),
                     static_cast<ULONG>(data.size()), 0) < 0 ||
      BCryptFinishHash(hash, digest.data(), hash_bytes, 0) < 0;
  if (hash) BCryptDestroyHash(hash);
  BCryptCloseAlgorithmProvider(algorithm, 0);
  if (failed) throw Error("SHA256_FAILED", "Could not hash the skin calibration.", 500);
  std::ostringstream output;
  output << std::hex << std::setfill('0');
  for (const auto byte : digest) output << std::setw(2) << static_cast<int>(byte);
  return output.str();
#else
  throw Error("SHA256_UNSUPPORTED", "Skin calibration hashing requires Windows.", 500);
#endif
}

std::string ReadRequestedDeviceProfile(const std::filesystem::path& input_directory) {
  const auto path = input_directory / "device_profile.txt";
  if (!std::filesystem::is_regular_file(path)) return {};
  std::ifstream stream(path, std::ios::binary);
  std::string value;
  std::getline(stream, value);
  if (value.empty() || value.size() > 64 ||
      !std::all_of(value.begin(), value.end(), [](unsigned char character) {
        return std::isalnum(character) || character == '_' || character == '-' ||
               character == '.';
      })) {
    throw Error("DEVICE_PROFILE_INVALID",
                "The device profile identifier contains unsupported characters.", 422);
  }
  return value;
}

MobileDeviceProfile LoadDeviceProfile(const std::filesystem::path& path,
                                      const std::string& requested_id) {
  std::ifstream stream(path, std::ios::binary);
  if (!stream) {
    throw Error("DEVICE_PROFILES_MISSING", "Mobile device profiles are missing.", 503);
  }
  const nlohmann::json root = nlohmann::json::parse(stream);
  const auto& profiles = root.at("profiles");
  if (!profiles.contains("generic")) {
    throw Error("DEVICE_PROFILES_INVALID", "A generic device profile is required.", 503);
  }
  MobileDeviceProfile result;
  result.requested_id = requested_id;
  result.resolved_id = profiles.contains(requested_id) ? requested_id : "generic";
  result.used_generic_fallback = result.resolved_id != requested_id;
  result.version = root.value("version", "unknown");
  result.sha256 = Sha256File(path);
  const auto& profile = profiles.at(result.resolved_id);
  result.calibrated = profile.value("calibrated", false);
  const auto& matrix = profile.at("linear_rgb_matrix");
  const auto& gain = profile.at("linear_rgb_gain");
  if (matrix.size() != 3 || gain.size() != 3) {
    throw Error("DEVICE_PROFILES_INVALID", "Device RGB calibration has invalid dimensions.",
                503);
  }
  for (int row = 0; row < 3; ++row) {
    if (matrix.at(row).size() != 3) {
      throw Error("DEVICE_PROFILES_INVALID", "Device RGB matrix must be 3 by 3.", 503);
    }
    for (int column = 0; column < 3; ++column) {
      result.linear_rgb_matrix(row, column) = matrix.at(row).at(column).get<float>();
    }
    result.linear_rgb_gain[row] = gain.at(row).get<float>();
  }
  return result;
}

SkinCalibration LoadCalibration(const std::filesystem::path& path) {
  std::ifstream stream(path, std::ios::binary);
  if (!stream) throw Error("SKIN_CALIBRATION_MISSING", "Skin calibration file is missing.", 503);
  const nlohmann::json json = nlohmann::json::parse(stream);
  SkinCalibration value;
  value.version = json.at("version").get<std::string>();
  value.threshold_mad = json.at("candidate_threshold_mad").get<double>();
  value.minimum_component_ratio =
      json.at("minimum_component_face_ratio").get<double>();
  const auto red_weights = json.at("red_weights");
  value.red_weights = {red_weights.at("inverse_luminance").get<double>(),
                       red_weights.at("chromatic_redness").get<double>(),
                       red_weights.at("local_detail").get<double>()};
  const auto brown_weights = json.at("brown_weights");
  value.brown_weights = {brown_weights.at("inverse_luminance").get<double>(),
                         brown_weights.at("melanin_proxy").get<double>(),
                         brown_weights.at("local_detail").get<double>()};
  const auto load_palette = [](const nlohmann::json& palette) {
    std::vector<cv::Vec3b> colors;
    for (const auto& rgb : palette) {
      colors.emplace_back(rgb.at(2).get<unsigned char>(), rgb.at(1).get<unsigned char>(),
                          rgb.at(0).get<unsigned char>());
    }
    if (colors.size() < 2) throw Error("SKIN_CALIBRATION_INVALID", "Palette is too short.", 503);
    return colors;
  };
  value.red_palette = load_palette(json.at("red_palette_rgb"));
  value.brown_palette = load_palette(json.at("brown_palette_rgb"));
  const auto load_regression = [](const nlohmann::json& coefficients) {
    if (coefficients.size() != 11) {
      throw Error("SKIN_CALIBRATION_INVALID", "Regression must contain 11 features.", 503);
    }
    std::array<cv::Vec3d, 11> result{};
    for (std::size_t feature = 0; feature < result.size(); ++feature) {
      result[feature] = {coefficients[feature].at(0).get<double>(),
                         coefficients[feature].at(1).get<double>(),
                         coefficients[feature].at(2).get<double>()};
    }
    return result;
  };
  value.red_regression = load_regression(json.at("red_regression_rgb"));
  value.brown_regression = load_regression(json.at("brown_regression_rgb"));
  if (json.contains("red_detail_regression_rgb") &&
      json.contains("brown_detail_regression_rgb")) {
    const auto load_detail = [](const nlohmann::json& coefficients) {
      if (coefficients.size() != 4) {
        throw Error("SKIN_CALIBRATION_INVALID",
                    "Detail regression must contain four features.", 503);
      }
      std::array<cv::Vec3d, 4> result{};
      for (std::size_t feature = 0; feature < result.size(); ++feature) {
        result[feature] = {coefficients[feature].at(0).get<double>(),
                           coefficients[feature].at(1).get<double>(),
                           coefficients[feature].at(2).get<double>()};
      }
      return result;
    };
    value.red_detail_regression = load_detail(json.at("red_detail_regression_rgb"));
    value.brown_detail_regression = load_detail(json.at("brown_detail_regression_rgb"));
    const auto sigmas = json.at("detail_sigmas_px");
    if (sigmas.size() != 3) {
      throw Error("SKIN_CALIBRATION_INVALID", "Three detail sigmas are required.", 503);
    }
    for (std::size_t index = 0; index < value.detail_sigmas.size(); ++index) {
      value.detail_sigmas[index] = sigmas[index].get<double>();
    }
    value.reference_max_dimension = json.value("reference_max_dimension", 5472.0);
    value.detail_clip = json.value("detail_clip", 0.18);
    value.tile_size = json.value("tile_size", 1024);
    value.full_resolution_style = json.value("full_resolution_render", true);
    const auto load_curve = [&json](const char* name,
                                    std::array<double, 5>& destination) {
      const auto curve = json.at(name);
      if (curve.size() != destination.size()) {
        throw Error("SKIN_CALIBRATION_INVALID",
                    "Tone curves must contain five control points.", 503);
      }
      for (std::size_t index = 0; index < destination.size(); ++index) {
        destination[index] = curve[index].get<double>();
      }
    };
    load_curve("red_tone_input", value.red_tone_input);
    load_curve("red_tone_output", value.red_tone_output);
    load_curve("brown_tone_input", value.brown_tone_input);
