cv::Vec3b PaletteColor(const std::vector<cv::Vec3b>& palette, float value) {
  const float scaled = std::clamp(value, 0.0F, 1.0F) *
                       static_cast<float>(palette.size() - 1);
  const std::size_t left = static_cast<std::size_t>(std::floor(scaled));
  const std::size_t right = std::min(left + 1, palette.size() - 1);
  const float amount = scaled - static_cast<float>(left);
  cv::Vec3b color;
  for (int channel = 0; channel < 3; ++channel) {
    color[channel] = cv::saturate_cast<unsigned char>(
        (1.0F - amount) * palette[left][channel] + amount * palette[right][channel]);
  }
  return color;
}

cv::Mat ColorizeStyle(const cv::Mat& intensity, const cv::Mat& face_mask,
                      const std::vector<cv::Vec3b>& palette) {
  cv::Mat output(intensity.size(), CV_8UC3, cv::Scalar(255, 255, 255));
  for (int y = 0; y < output.rows; ++y) {
    const float* score = intensity.ptr<float>(y);
    const unsigned char* mask = face_mask.ptr<unsigned char>(y);
    auto* pixels = output.ptr<cv::Vec3b>(y);
    for (int x = 0; x < output.cols; ++x) {
      if (mask[x] != 0) pixels[x] = PaletteColor(palette, score[x]);
    }
  }
  return output;
}

cv::Vec3d BaseStyleRgb(const cv::Vec3b& source,
                       const std::array<cv::Vec3d, 11>& coefficients) {
  const double red = source[2] / 255.0;
  const double green = source[1] / 255.0;
  const double blue = source[0] / 255.0;
  const double total = std::max(1e-3, red + green + blue);
  const std::array<double, 11> features = {
      1.0,
      red,
      green,
      blue,
      std::log(std::max(1e-3, red)),
      std::log(std::max(1e-3, green)),
      std::log(std::max(1e-3, blue)),
      red - green,
      green - blue,
      red / total,
      green / total,
  };
  cv::Vec3d rgb(0.0, 0.0, 0.0);
  for (std::size_t feature = 0; feature < features.size(); ++feature) {
    rgb += features[feature] * coefficients[feature];
  }
  return rgb;
}

cv::Mat RegressionStyle(const cv::Mat& image, const cv::Mat& face_mask,
                         const std::array<cv::Vec3d, 11>& coefficients) {
  cv::Mat output(image.size(), CV_8UC3, cv::Scalar(255, 255, 255));
  for (int y = 0; y < image.rows; ++y) {
    const auto* source = image.ptr<cv::Vec3b>(y);
    const auto* mask = face_mask.empty() ? nullptr : face_mask.ptr<unsigned char>(y);
    auto* target = output.ptr<cv::Vec3b>(y);
    for (int x = 0; x < image.cols; ++x) {
      if (mask != nullptr && mask[x] == 0) continue;
      const cv::Vec3d rgb = BaseStyleRgb(source[x], coefficients);
      target[x] = cv::Vec3b(cv::saturate_cast<unsigned char>(255.0 * rgb[2]),
                            cv::saturate_cast<unsigned char>(255.0 * rgb[1]),
                            cv::saturate_cast<unsigned char>(255.0 * rgb[0]));
    }
  }
  return output;
}

cv::Mat FullResolutionSoftMatte(const cv::Mat& analysis_mask,
                                const cv::Size& output_size) {
  cv::Mat matte;
  cv::resize(analysis_mask, matte, output_size, 0.0, 0.0, cv::INTER_LINEAR);
  cv::GaussianBlur(matte, matte, {0, 0}, 1.6, 1.6, cv::BORDER_REPLICATE);
  return matte;
}

struct FullResolutionStyles {
  cv::Mat red;
  cv::Mat brown;
  cv::Mat matte;
