  const double median_g = std::max(1e-4, SamplePercentile(channels[1], analysis_mask, 0.5));
  const double median_r = std::max(1e-4, SamplePercentile(channels[2], analysis_mask, 0.5));
  const double target_median = (median_b + median_g + median_r) / 3.0;
  channels[0] *= target_median / median_b;
  channels[1] *= target_median / median_g;
  channels[2] *= target_median / median_r;
  for (auto& channel : channels) cv::min(channel, 1.0, channel);

  const double illumination_sigma = std::max(3.0, face.width * 0.08);
  std::vector<cv::Mat> normalized_channels(3);
  for (int channel = 0; channel < 3; ++channel) {
    cv::Mat illumination;
    cv::GaussianBlur(channels[channel], illumination, {0, 0}, illumination_sigma);
    normalized_channels[channel] = channels[channel] / (illumination + 1e-4F);
  }

  cv::Mat log_r;
  cv::Mat log_g;
  cv::log(normalized_channels[2] + 1e-4F, log_r);
  cv::log(normalized_channels[1] + 1e-4F, log_g);
  const cv::Mat redness = log_r - log_g;
  cv::Mat optical_density_r;
  cv::log(normalized_channels[2] + 1e-4F, optical_density_r);
  optical_density_r *= -1.0F;
  cv::Mat positive_redness;
  cv::max(redness, 0.0, positive_redness);
  const cv::Mat melanin = optical_density_r - 0.35F * positive_redness;

  const cv::Mat redness_normalized = PercentileNormalize(redness, face_mask);
  std::optional<PhysicalScoreMaps> physical_scores;
  if (v3_requested) {
