                                              config.min_blur_score);
  }
  progress(58, "rendering_instrument_style_maps");

  FullResolutionStyles styles =
      RenderFullResolutionStyles(original, face_mask, calibration);
  WriteImage(output / "RED_M.jpg", styles.red, 98);
  WriteImage(output / "BROWN_M.jpg", styles.brown, 98);

  cv::Mat redness_full;
  cv::resize(redness_normalized, redness_full, original.size(), 0.0, 0.0,
