      redness_z, analysis_mask, calibration.threshold_mad, minimum_component);
  const cv::Mat pigmentation_mask = FilterCandidates(
      melanin_z, analysis_mask, calibration.threshold_mad, minimum_component);
  const cv::Mat erythema_full =
      ResizeResult(erythema_mask, original.size(), cv::INTER_NEAREST);
  const cv::Mat pigmentation_full =
      ResizeResult(pigmentation_mask, original.size(), cv::INTER_NEAREST);
  WriteImage(output / "erythema_mask.png", erythema_full);
  WriteImage(output / "pigmentation_mask.png", pigmentation_full);
  WriteImage(output / "erythema_overlay.png",
             OverlayCandidates(original, erythema_full, cv::Vec3b(70, 60, 230)));
  WriteImage(output / "pigmentation_overlay.png",
             OverlayCandidates(original, pigmentation_full, cv::Vec3b(45, 100, 170)));
  if (physical_scores.has_value()) {
    WriteFullResolutionScore(output / "red_score.png", physical_scores->red,
                             analysis_mask, original.size(), true);
    WriteFullResolutionScore(output / "brown_score.png", physical_scores->brown,
                             analysis_mask, original.size(), true);
    WriteFullResolutionScore(output / "confidence.png", physical_scores->confidence,
                             analysis_mask, original.size(), false);
