  WriteRgbReviewArtifacts(original, styles.red, styles.brown, output);

  const double erythema_ratio =
      static_cast<double>(cv::countNonZero(erythema_mask)) / skin_pixels;
  const double pigmentation_ratio =
      static_cast<double>(cv::countNonZero(pigmentation_mask)) / skin_pixels;
  const nlohmann::json detection = {
      {"candidate_only", true},
      {"vendor_equivalent", false},
      {"trend_eligible", false},
      {"threshold_mad", calibration.threshold_mad},
      {"minimum_component_pixels", minimum_component},
      {"erythema_area_ratio", erythema_ratio},
      {"pigmentation_area_ratio", pigmentation_ratio},
      {"erythema_components", ComponentCount(erythema_mask)},
      {"pigmentation_components", ComponentCount(pigmentation_mask)},
  };
  std::ofstream(output / "detection.json", std::ios::binary) << detection.dump(2);

  const double total_seconds =
      std::chrono::duration<double>(Clock::now() - started_at).count();
  nlohmann::json quality = {
      {"backend", "rgb_visual_approximation_v2"},
      {"source_modalities", {"RGB"}},
      {"vendor_adapter_used", false},
      {"instrument_style", true},
      {"candidate_regions_only", true},
      {"vendor_equivalent", false},
      {"trend_eligible", false},
      {"trend_ineligible_reason",
       "Single-RGB visual approximation is not equivalent to CP/365 analysis."},
      {"measurement_grade", false},
      {"diagnostic_grade", false},
      {"brightness", brightness},
      {"blur_score", blur_score},
      {"face_detection_method", face_detection.method},
      {"matte_method", masks.method},
      {"input_width", original.cols},
      {"input_height", original.rows},
      {"analysis_width", image.cols},
      {"analysis_height", image.rows},
      {"render_width", original.cols},
      {"render_height", original.rows},
      {"full_resolution_render", true},
      {"geometry_preserved", true},
      {"face_pixels", static_cast<long long>(face_pixels / (processing_scale * processing_scale))},
      {"skin_pixels", static_cast<long long>(skin_pixels / (processing_scale * processing_scale))},
      {"skin_mask_coverage", static_cast<double>(skin_pixels) / face_pixels},
      {"erythema_area_ratio", erythema_ratio},
      {"pigmentation_area_ratio", pigmentation_ratio},
      {"erythema_components", ComponentCount(erythema_mask)},
      {"pigmentation_components", ComponentCount(pigmentation_mask)},
      {"detail_energy_red", styles.red_detail_energy},
      {"detail_energy_brown", styles.brown_detail_energy},
      {"calibration_version", calibration.version},
