                "Could not finish the RGB v2 calibration file.", 500);
  }
}

PipelineResult RunSkinMapPipeline(const std::string&, const std::string& kind,
                                  const std::filesystem::path& job_directory,
                                  const Config& config, const ProgressCallback& progress) {
  const auto canonical_job = std::filesystem::weakly_canonical(job_directory);
  const auto canonical_root = std::filesystem::weakly_canonical(config.jobs_dir);
  if (canonical_job.parent_path() != canonical_root) {
    throw Error("UNSAFE_SKIN_JOB_PATH", "Skin-map job path is outside the job root.", 500);
  }
  if (kind == "skin_instrument") {
    return RunVendorPipeline(job_directory, config, progress);
  }
  if (kind == "skin_rgb") {
    return RunRgbPipeline(job_directory, config, progress);
  }
  throw Error("UNKNOWN_SKIN_JOB_KIND", "Unknown skin-map job kind.", 400,
              {{"kind", kind}});
}

}  // namespace skinmap

