using Clock = std::chrono::steady_clock;
using Deadline = Clock::time_point;

[[noreturn]] void ThrowDeadline(const std::string& stage,
                                int total_seconds) {
  throw Error("VENDOR_SKIN_DEADLINE_EXCEEDED",
              "Vendor skin operation exceeded its shared time budget.", 504,
              {{"stage", stage}, {"total_budget_seconds", total_seconds}});
}

std::pair<time_t, time_t> TimeoutValue(Deadline deadline,
                                       std::chrono::milliseconds maximum,
                                       const std::string& stage,
                                       int total_seconds) {
  const auto now = Clock::now();
  if (now >= deadline) ThrowDeadline(stage, total_seconds);
  auto remaining = std::chrono::duration_cast<std::chrono::microseconds>(deadline - now);
  remaining = std::min(remaining,
                       std::chrono::duration_cast<std::chrono::microseconds>(maximum));
  remaining = std::max(remaining, std::chrono::microseconds(1));
  const auto seconds = std::chrono::duration_cast<std::chrono::seconds>(remaining);
  const auto microseconds =
      std::chrono::duration_cast<std::chrono::microseconds>(remaining - seconds);
  return {static_cast<time_t>(seconds.count()),
          static_cast<time_t>(microseconds.count())};
}

void ConfigureTimeouts(httplib::Client& client, Deadline deadline,
                       const std::string& stage, int total_seconds,
                       std::chrono::milliseconds read_cap) {
  const auto [connection_seconds, connection_microseconds] =
      TimeoutValue(deadline, std::chrono::seconds(5), stage, total_seconds);
  const auto [write_seconds, write_microseconds] =
      TimeoutValue(deadline, std::chrono::seconds(10), stage, total_seconds);
  const auto [read_seconds, read_microseconds] =
      TimeoutValue(deadline, read_cap, stage, total_seconds);
  client.set_connection_timeout(connection_seconds, connection_microseconds);
  client.set_write_timeout(write_seconds, write_microseconds);
  client.set_read_timeout(read_seconds, read_microseconds);
}

std::string Utf8Path(const std::filesystem::path& path) {
  const auto value = path.u8string();
  return std::string(value.begin(), value.end());
}

bool Probe(const Config& config, Deadline deadline) {
  httplib::Client client(config.vendor_skin_host, config.vendor_skin_port);
  ConfigureTimeouts(client, deadline, "startup_probe",
                    config.vendor_skin_total_seconds, std::chrono::seconds(2));
  const auto response = client.Get("/test");
  if (Clock::now() >= deadline) {
    ThrowDeadline("startup_probe", config.vendor_skin_total_seconds);
  }
  return response && response->status == 200;
}

struct StartedProcess {
  std::mutex mutex;
#ifdef _WIN32
  HANDLE handle{nullptr};
#endif
  bool owned{false};

  ~StartedProcess() {
#ifdef _WIN32
    if (owned && handle != nullptr) {
      DWORD exit_code = 0;
      if (GetExitCodeProcess(handle, &exit_code) && exit_code == STILL_ACTIVE) {
        TerminateProcess(handle, 0);
        WaitForSingleObject(handle, 5000);
      }
      CloseHandle(handle);
    }
#endif
  }
};

StartedProcess& ProcessState() {
  static StartedProcess process;
  return process;
}

#ifdef _WIN32
bool ContainsNonAscii(const std::filesystem::path& path) {
  const std::wstring value = path.wstring();
  return std::any_of(value.begin(), value.end(),
                     [](wchar_t character) { return character > 127; });
}

std::filesystem::path ResolveVendorExecutable(const Config& config) {
  if (!ContainsNonAscii(config.vendor_skin_exe_path)) {
    return config.vendor_skin_exe_path;
  }
  const wchar_t* local_app_data = _wgetenv(L"LOCALAPPDATA");
  if (local_app_data == nullptr || *local_app_data == L'\0') {
    throw Error("VENDOR_SKIN_ASCII_LINK_FAILED",
                "LOCALAPPDATA is required to create the vendor ASCII junction.", 503);
  }
  const auto link = std::filesystem::path(local_app_data) / "SkinMapLocal" /
                    "VendorEngine";
  const auto linked_executable = link / "XingerEngine.exe";
  if (std::filesystem::is_regular_file(linked_executable)) return linked_executable;
  if (std::filesystem::exists(link)) {
    throw Error("VENDOR_SKIN_ASCII_LINK_CONFLICT",
                "The vendor ASCII link path already exists but is not usable.", 503,
                {{"path", Utf8Path(link)}});
  }
  std::filesystem::create_directories(link.parent_path());
  const auto target = config.vendor_skin_exe_path.parent_path();
  std::wstring command = L"cmd.exe /D /C mklink /J \"" + link.wstring() +
                         L"\" \"" + target.wstring() + L"\"";
  std::vector<wchar_t> mutable_command(command.begin(), command.end());
  mutable_command.push_back(L'\0');
  STARTUPINFOW startup{};
  startup.cb = sizeof(startup);
  PROCESS_INFORMATION process{};
  if (!CreateProcessW(nullptr, mutable_command.data(), nullptr, nullptr, FALSE,
                      CREATE_NO_WINDOW, nullptr, nullptr, &startup, &process)) {
    throw Error("VENDOR_SKIN_ASCII_LINK_FAILED",
                "Could not launch the vendor ASCII junction helper.", 503,
                {{"windows_error", static_cast<int>(GetLastError())}});
  }
  CloseHandle(process.hThread);
  const DWORD wait = WaitForSingleObject(process.hProcess, 10000);
  DWORD exit_code = 1;
  GetExitCodeProcess(process.hProcess, &exit_code);
  CloseHandle(process.hProcess);
  if (wait != WAIT_OBJECT_0 || exit_code != 0 ||
      !std::filesystem::is_regular_file(linked_executable)) {
    throw Error("VENDOR_SKIN_ASCII_LINK_FAILED",
                "Could not create the vendor ASCII directory junction.", 503,
                {{"path", Utf8Path(link)}, {"exit_code", exit_code}});
  }
  return linked_executable;
}
#else
std::filesystem::path ResolveVendorExecutable(const Config& config) {
  return config.vendor_skin_exe_path;
}
#endif

std::pair<double, bool> EnsureRunning(const Config& config, Deadline deadline) {
  if (Probe(config, deadline)) return {0.0, false};
  if (!config.vendor_skin_autostart) {
    throw Error("VENDOR_SKIN_SERVICE_UNAVAILABLE",
                "Vendor skin service is unavailable and autostart is disabled.", 503);
  }
  const auto executable = ResolveVendorExecutable(config);
  if (!std::filesystem::is_regular_file(executable)) {
    throw Error("VENDOR_SKIN_EXECUTABLE_MISSING", "Vendor skin executable was not found.", 503,
                {{"path", Utf8Path(executable)}});
  }

  auto& state = ProcessState();
  std::scoped_lock lock(state.mutex);
  if (Probe(config, deadline)) return {0.0, false};

#ifdef _WIN32
  if (state.handle != nullptr) {
    DWORD exit_code = 0;
    if (!GetExitCodeProcess(state.handle, &exit_code) || exit_code != STILL_ACTIVE) {
      CloseHandle(state.handle);
      state.handle = nullptr;
      state.owned = false;
    }
  }
  bool started_now = false;
  if (state.handle == nullptr) {
    STARTUPINFOW startup{};
    startup.cb = sizeof(startup);
    PROCESS_INFORMATION process{};
    std::wstring command = L"\"" + executable.wstring() + L"\"";
    std::vector<wchar_t> mutable_command(command.begin(), command.end());
    mutable_command.push_back(L'\0');
    const std::wstring working_directory = executable.parent_path().wstring();
    if (!CreateProcessW(executable.c_str(), mutable_command.data(), nullptr,
                        nullptr, FALSE, CREATE_NO_WINDOW, nullptr, working_directory.c_str(),
                        &startup, &process)) {
      throw Error("VENDOR_SKIN_START_FAILED", "Could not start the vendor skin service.", 503,
                  {{"windows_error", static_cast<int>(GetLastError())}});
    }
    CloseHandle(process.hThread);
    state.handle = process.hProcess;
    state.owned = true;
    started_now = true;
  }
#else
  throw Error("VENDOR_SKIN_START_UNSUPPORTED",
              "Automatic vendor service startup is supported only on Windows.", 503);
#endif

  const auto started_at = Clock::now();
  const auto startup_deadline = std::min(
      deadline, started_at + std::chrono::seconds(config.vendor_skin_startup_seconds));
  while (Clock::now() < startup_deadline) {
    if (Probe(config, deadline)) {
      return {std::chrono::duration<double>(Clock::now() - started_at).count(), started_now};
    }
#ifdef _WIN32
    if (state.handle != nullptr && WaitForSingleObject(state.handle, 0) == WAIT_OBJECT_0) {
      throw Error("VENDOR_SKIN_START_FAILED",
                  "Vendor skin service exited before becoming ready.", 503);
    }
#endif
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
  }
  if (Clock::now() >= deadline) {
    ThrowDeadline("startup", config.vendor_skin_total_seconds);
  }
  throw Error("VENDOR_SKIN_START_TIMEOUT", "Vendor skin service startup timed out.", 504,
              {{"timeout_seconds", config.vendor_skin_startup_seconds}});
}

nlohmann::json PostFolder(const Config& config, const char* endpoint,
                          const std::filesystem::path& input_directory,
                          Deadline deadline) {
  httplib::Client client(config.vendor_skin_host, config.vendor_skin_port);
  const std::string stage = endpoint;
  ConfigureTimeouts(client, deadline, stage, config.vendor_skin_total_seconds,
                    std::chrono::seconds(config.vendor_skin_total_seconds));
  httplib::Params parameters;
  parameters.emplace("image_fold_path", Utf8Path(input_directory));
  const auto response = client.Post(endpoint, parameters);
  if (!response) {
    if (Clock::now() + std::chrono::milliseconds(20) >= deadline) {
      ThrowDeadline(stage, config.vendor_skin_total_seconds);
    }
    throw Error("VENDOR_SKIN_REQUEST_FAILED", "Vendor skin service request failed.", 502,
                {{"endpoint", endpoint}, {"transport_error", httplib::to_string(response.error())}});
  }
  if (Clock::now() >= deadline) {
    ThrowDeadline(stage, config.vendor_skin_total_seconds);
  }
  if (response->status < 200 || response->status >= 300) {
    throw Error("VENDOR_SKIN_REQUEST_REJECTED", "Vendor skin service rejected the request.",
                502, {{"endpoint", endpoint}, {"status", response->status},
                      {"body", response->body}});
  }
  try {
    return nlohmann::json::parse(response->body);
  } catch (const std::exception&) {
    return {{"status", response->status}, {"raw_body", response->body}};
  }
}

}  // namespace

VendorSkinAdapter::VendorSkinAdapter(const Config& config) : config_(config) {}

VendorSkinResult VendorSkinAdapter::Run(
    const std::filesystem::path& input_directory) const {
  if (!std::filesystem::is_directory(input_directory)) {
    throw Error("VENDOR_SKIN_INPUT_MISSING", "Vendor skin input directory does not exist.", 422);
  }
  VendorSkinResult result;
  const auto deadline =
      Clock::now() + std::chrono::seconds(config_.vendor_skin_total_seconds);
  const auto [startup_seconds, started] = EnsureRunning(config_, deadline);
  result.startup_seconds = startup_seconds;
  result.process_started = started;

  auto started_at = Clock::now();
  PostFolder(config_, "/generate", input_directory, deadline);
  result.generate_seconds = std::chrono::duration<double>(Clock::now() - started_at).count();

  started_at = Clock::now();
  result.detection = PostFolder(config_, "/detect", input_directory, deadline);
  result.detect_seconds = std::chrono::duration<double>(Clock::now() - started_at).count();
  return result;
}

void StopOwnedVendorSkinProcess() {
  auto& state = ProcessState();
  std::scoped_lock lock(state.mutex);
#ifdef _WIN32
  if (state.owned && state.handle != nullptr) {
    DWORD exit_code = 0;
    if (GetExitCodeProcess(state.handle, &exit_code) && exit_code == STILL_ACTIVE) {
      TerminateProcess(state.handle, 0);
      WaitForSingleObject(state.handle, 5000);
    }
    CloseHandle(state.handle);
    state.handle = nullptr;
    state.owned = false;
  }
#endif
}

