int Run(const Arguments& arguments) {
  if (arguments.input_directory.empty() || arguments.output.empty()) {
    throw std::runtime_error("Both --input-dir and --output are required.");
  }
  const auto input = std::filesystem::absolute(arguments.input_directory);
  if (!std::filesystem::is_directory(input)) {
    throw std::runtime_error("The instrument input directory does not exist.");
  }
  const auto root = arguments.project_root.empty()
                        ? FindProjectRoot(std::filesystem::current_path())
                        : FindProjectRoot(arguments.project_root);
  const auto output = std::filesystem::absolute(arguments.output);
  skinmap::PrepareEmptyOutputDirectory(output);

  const std::array<const char*, 9> required_names = {
      "RGB_M.jpg", "RGB_L.jpg", "RGB_R.jpg", "CP_M.jpg", "CP_L.jpg",
      "CP_R.jpg",  "365_M.jpg", "365_L.jpg", "365_R.jpg"};
  const std::array<const char*, 3> optional_pp_names = {
      "PP_M.jpg", "PP_L.jpg", "PP_R.jpg"};
  const auto nonce = std::chrono::steady_clock::now().time_since_epoch().count();
  const auto staging = std::filesystem::temp_directory_path() /
                       ("skinmap_instrument_" + std::to_string(nonce));
  const auto job = staging / "job";
  std::filesystem::create_directories(job / "input");
  std::filesystem::create_directories(job / "output");

  try {
    for (const char* name : required_names) {
      const auto source = input / name;
      if (!std::filesystem::is_regular_file(source)) {
        throw skinmap::Error("MISSING_MODALITY",
                             "The complete RGB, CP and 365 image set is required.",
                             422, {{"missing", {name}}});
      }
      std::filesystem::copy_file(source, job / "input" / name);
    }
    for (const char* name : optional_pp_names) {
      const auto source = input / name;
      if (std::filesystem::is_regular_file(source)) {
        std::filesystem::copy_file(source, job / "input" / name);
      }
    }

    skinmap::Config config = skinmap::Config::FromEnvironment(root);
    config.jobs_dir = staging;
    if (!arguments.vendor_engine.empty()) {
      const auto supplied = std::filesystem::absolute(arguments.vendor_engine);
      if (std::filesystem::is_directory(supplied)) {
        config.vendor_skin_engine_root = supplied;
        config.vendor_skin_exe_path = supplied / "XingerEngine.exe";
      } else {
        config.vendor_skin_exe_path = supplied;
        config.vendor_skin_engine_root = supplied.parent_path();
      }
    }
    const skinmap::PipelineResult result = skinmap::RunSkinMapPipeline(
        "00000000000000000000000000000000", "skin_instrument", job, config,
        [](int percent, const std::string& stage) {
          std::cout << percent << "% " << stage << '\n';
        });
    for (const auto& entry : std::filesystem::directory_iterator(job / "output")) {
      if (entry.is_regular_file()) {
        std::filesystem::copy_file(entry.path(), output / entry.path().filename(),
                                   std::filesystem::copy_options::overwrite_existing);
      }
    }
    nlohmann::json quality = result.quality;
    quality["entrypoint"] = "skin_map_instrument_cli";
    std::ofstream(output / "quality.json", std::ios::binary | std::ios::trunc)
        << quality.dump(2) << '\n';
    skinmap::StopOwnedVendorSkinProcess();
    std::error_code cleanup_error;
    std::filesystem::remove_all(staging, cleanup_error);
    std::cout << quality.dump(2) << '\n';
    return 0;
  } catch (...) {
    skinmap::StopOwnedVendorSkinProcess();
    std::error_code ignored;
    std::filesystem::remove_all(staging, ignored);
    throw;
  }
}

