std::optional<std::filesystem::path> TryFindProjectRoot(
    std::filesystem::path candidate) {
  candidate = std::filesystem::absolute(candidate);
  for (int depth = 0; depth < 6; ++depth) {
    if (IsProjectRoot(candidate)) return candidate;
    if (candidate == candidate.parent_path()) break;
    candidate = candidate.parent_path();
  }
  return std::nullopt;
}

std::filesystem::path FindProjectRoot(const std::filesystem::path& candidate) {
  if (const auto root = TryFindProjectRoot(candidate); root.has_value()) return *root;
#ifdef _WIN32
