cv::Mat FitReviewPanel(const cv::Mat& source, int height) {
  const int width = std::max(1, source.cols * height / source.rows);
  cv::Mat result;
  cv::resize(source, result, {width, height}, 0.0, 0.0, cv::INTER_AREA);
  return result;
}

