nlohmann::json PostFolder(const Config& config, const char* endpoint,
                          const std::filesystem::path& input_directory) {
  httplib::Client client(config.vendor_skin_host, config.vendor_skin_port);
  client.set_connection_timeout(5, 0);
  client.set_write_timeout(10, 0);
  client.set_read_timeout(300, 0);
  httplib::Params parameters;
  parameters.emplace("image_fold_path", Utf8Path(input_directory));
  const auto response = client.Post(endpoint, parameters);
  if (!response) {
    throw Error("VENDOR_SKIN_REQUEST_FAILED", "Vendor skin service request failed.", 502,
                {{"endpoint", endpoint}, {"transport_error", httplib::to_string(response.error())}});
  }
  if (response->status < 200 || response->status >= 300) {
    throw Error("VENDOR_SKIN_REQUEST_REJECTED", "Vendor skin service rejected the request.",
                502, {{"endpoint", endpoint}, {"status", response->status},
                      {"body", response->body}});
  }
  try {
    return nlohmann::json::parse(response->body);
  } catch (const std::exception&) {
    return {{"status", response->status}, {"raw_body", response->body}};
  }
}

