std::string Lower(std::string value) {
  std::transform(value.begin(), value.end(), value.begin(), [](unsigned char character) {
    return static_cast<char>(std::tolower(character));
  });
  return value;
}

bool IsSafeImageName(const std::string& value) {
  if (value.empty() || value.find('/') != std::string::npos ||
      value.find('\\') != std::string::npos || value.find(':') != std::string::npos) {
    return false;
  }
  const std::string extension = Lower(std::filesystem::path(value).extension().string());
  return extension == ".png" || extension == ".jpg" || extension == ".jpeg";
}

const nlohmann::json& ResponseRoot(const nlohmann::json& response) {
  if (response.is_object() && response.contains("vendor_response") &&
      response.at("vendor_response").is_object()) {
    return response.at("vendor_response");
  }
  return response;
}

void MergePayload(nlohmann::json& destination, const nlohmann::json& incoming,
                  const std::string& canonical, const std::string& source,
                  nlohmann::json& conflicts) {
  if (!incoming.is_object()) return;
  for (const auto& [key, value] : incoming.items()) {
    if (!destination.contains(key)) {
      destination[key] = value;
    } else if (destination.at(key) != value) {
      conflicts.push_back({{"finding", canonical},
                           {"field", key},
                           {"preferred_value", destination.at(key)},
                           {"conflicting_source", source},
                           {"conflicting_value", value}});
    }
  }
}

nlohmann::json ExtractCounts(const nlohmann::json& payload) {
  nlohmann::json counts = nlohmann::json::object();
  if (!payload.is_object()) return counts;
  for (const auto& [key, value] : payload.items()) {
    if (key == "count" || key == "category" || key.starts_with("number") ||
        key.starts_with("num_")) {
      counts[key] = value;
    }
  }
  return counts;
}

nlohmann::json ExtractPercentages(const nlohmann::json& payload) {
  nlohmann::json percentages = nlohmann::json::object();
  if (!payload.is_object()) return percentages;
  for (const auto& [key, value] : payload.items()) {
    if (key == "part_percentages" || key.starts_with("percentage")) {
      percentages[key] = value;
    }
  }
  return percentages;
}

nlohmann::json ExtractViews(const nlohmann::json& payload) {
  nlohmann::json views = nlohmann::json::object();
  if (!payload.is_object()) return views;
  for (const auto& [key, value] : payload.items()) {
    if (key.starts_with("image_") || key.size() < 3 || key[key.size() - 2] != '_') {
      continue;
    }
    const char suffix = static_cast<char>(std::tolower(key.back()));
    if (suffix != 'l' && suffix != 'm' && suffix != 'r') continue;
    views[std::string(1, suffix)][key.substr(0, key.size() - 2)] = value;
  }
  return views;
}

void FindAvailableArtifacts(const nlohmann::json& value,
                            const std::set<std::string>& available,
                            std::set<std::string>& found, int depth = 0) {
  if (depth > 64) return;
  if (value.is_string()) {
    const std::string filename = value.get<std::string>();
    if (IsSafeImageName(filename) && available.contains(filename)) found.insert(filename);
    return;
  }
  if (value.is_array()) {
    for (const auto& child : value) {
      FindAvailableArtifacts(child, available, found, depth + 1);
    }
  } else if (value.is_object()) {
    for (const auto& [_, child] : value.items()) {
      FindAvailableArtifacts(child, available, found, depth + 1);
    }
  }
}

bool ArtifactMatchesDefinition(const std::string& filename,
                               const DetectionDefinition& definition) {
  const std::string lower = Lower(filename);
  const auto marker = lower.find("_image_enhence_");
  if (marker == std::string::npos) return false;
  const std::string prefix = lower.substr(0, marker);
  if (prefix == Lower(definition.id)) return true;
  return std::any_of(definition.vendor_fields.begin(), definition.vendor_fields.end(),
                     [&](const std::string& alias) {
                       return prefix == Lower(alias);
                     });
}

nlohmann::json Locations(const nlohmann::json& payload) {
  if (!payload.is_object() || !payload.contains("location") ||
      payload.at("location").is_null()) {
    return nlohmann::json::array();
  }
  if (payload.at("location").is_array()) return payload.at("location");
  return nlohmann::json::array({payload.at("location")});
}

