nlohmann::json VendorDetectionParser::Parse(
    const nlohmann::json& vendor_response,
    const VendorArtifactCollection& artifacts) {
  const auto& root = ResponseRoot(vendor_response);
  if (!root.is_object()) {
    throw Error("VENDOR_SKIN_RESPONSE_INVALID",
                "Vendor detection response is not an object.", 502);
  }
  if (!root.contains("status") || root.at("status") != 200) {
    throw Error("VENDOR_SKIN_BUSINESS_ERROR",
                "Vendor detection returned an unsuccessful business status.", 502,
                {{"business_status", root.value("status", nlohmann::json(nullptr))},
                 {"business_message", root.value("message", "")}});
  }
  if (!root.contains("data") || !root.at("data").is_object()) {
    throw Error("VENDOR_SKIN_RESPONSE_INVALID",
                "Vendor detection response does not contain an object data payload.", 502);
  }
  const auto& data = root.at("data");
  bool contains_known_finding = false;
  for (const auto& definition : DetectionCatalog::Findings()) {
    contains_known_finding = contains_known_finding ||
        std::any_of(definition.vendor_fields.begin(), definition.vendor_fields.end(),
                    [&](const std::string& alias) { return data.contains(alias); });
  }
  if (!contains_known_finding) {
    throw Error("VENDOR_SKIN_RESPONSE_EMPTY",
                "Vendor detection data contains no known canonical finding.", 502,
                {{"data_field_count", data.size()}});
  }
  nlohmann::json conflicts = nlohmann::json::array();
  nlohmann::json unknown = nlohmann::json::object();
  nlohmann::json findings = nlohmann::json::object();
  nlohmann::json finding_backend = nlohmann::json::object();
  std::set<std::string> recognized;

  for (const auto& definition : DetectionCatalog::Findings()) {
    nlohmann::json merged = nlohmann::json::object();
    nlohmann::json source_fields = nlohmann::json::array();
    for (const auto& alias : definition.vendor_fields) {
      recognized.insert(alias);
      if (!data.contains(alias)) continue;
      source_fields.push_back(alias);
      MergePayload(merged, data.at(alias), definition.id, alias, conflicts);
    }
    const bool available = !source_fields.empty();
    std::set<std::string> raw_overlays;
    FindAvailableArtifacts(merged, artifacts.available_names, raw_overlays);
    for (const auto& filename : artifacts.available_names) {
      if (ArtifactMatchesDefinition(filename, definition)) {
        raw_overlays.insert(filename);
      }
    }
    std::set<std::string> preview_artifacts;
    nlohmann::json artifact_pairs = nlohmann::json::array();
    for (const auto& raw_overlay : raw_overlays) {
      const auto preview = artifacts.preview_by_raw.find(raw_overlay);
      const nlohmann::json preview_name =
          preview == artifacts.preview_by_raw.end()
              ? nlohmann::json(nullptr)
              : nlohmann::json(preview->second);
      if (preview != artifacts.preview_by_raw.end()) {
        preview_artifacts.insert(preview->second);
      }
      artifact_pairs.push_back({{"raw_overlay", raw_overlay},
                                {"preview", preview_name},
                                {"default_artifact", preview_name}});
    }
    const auto level = merged.contains("level")
                           ? merged.at("level")
                           : merged.value("level_all", nlohmann::json(nullptr));
    findings[definition.id] = {
        {"group", definition.group},
        {"display_name_zh", definition.display_name_zh},
        {"availability", definition.availability},
        {"status", available ? "available" : "unavailable"},
        {"level", level},
        {"score", merged.value("score", nlohmann::json(nullptr))},
        {"counts", ExtractCounts(merged)},
        {"percentages", ExtractPercentages(merged)},
        {"locations", Locations(merged)},
        {"symmetry", merged.value("symmetry", nlohmann::json(nullptr))},
        {"views", ExtractViews(merged)},
        {"attributes", merged},
        {"artifacts", std::vector<std::string>(preview_artifacts.begin(),
                                                preview_artifacts.end())},
        {"raw_overlays", std::vector<std::string>(raw_overlays.begin(),
                                                   raw_overlays.end())},
        {"artifact_pairs", artifact_pairs},
        {"visualization_status",
         !preview_artifacts.empty()
             ? "preview_available"
             : (!raw_overlays.empty() ? "raw_overlay_only" : "json_only")},
        {"source_fields", source_fields},
    };
    finding_backend[definition.id] =
        available ? nlohmann::json("vendor_multispectral_exact")
                  : nlohmann::json(nullptr);
  }

  recognized.insert("detection_times");
  for (const auto& [key, value] : data.items()) {
    if (!recognized.contains(key)) unknown[key] = value;
  }

  nlohmann::json metadata = nlohmann::json::object();
  for (const char* key : {"status", "message"}) {
    if (root.contains(key)) metadata[key] = root.at(key);
  }
  if (data.contains("detection_times")) {
    metadata["detection_times"] = data.at("detection_times");
  }

  return {
      {"schema_version", "skin-analysis/1.0"},
      {"backend", "vendor_multispectral_exact"},
      {"findings", findings},
      {"finding_backend", finding_backend},
      {"vendor_metadata", metadata},
      {"unknown_vendor_fields", unknown},
      {"normalization_conflicts", conflicts},
      {"missing_declared_artifacts", artifacts.missing_references},
      {"unsafe_artifact_references", artifacts.unsafe_references},
      {"unreferenced_vendor_artifacts", artifacts.unreferenced_files},
      {"artifact_collisions", artifacts.collisions},
      {"invalid_vendor_artifacts", artifacts.invalid_images},
      {"artifact_limit_rejections", artifacts.limit_rejections},
      {"published_vendor_artifact_bytes", artifacts.copied_bytes},
      {"measurement_grade", false},
      {"diagnostic_grade", false},
  };
}

nlohmann::json VendorDetectionParser::Summary(const nlohmann::json& analysis) {
  std::size_t available = 0;
  std::size_t hidden_available = 0;
  std::map<std::string, std::size_t> groups;
  for (const auto& [_, finding] : analysis.at("findings").items()) {
    if (finding.value("status", "") != "available") continue;
    ++available;
    ++groups[finding.value("group", "unknown")];
    if (finding.value("availability", "") == "supported_hidden") {
      ++hidden_available;
    }
  }
  return {{"schema_version", analysis.at("schema_version")},
          {"backend", analysis.at("backend")},
          {"canonical_findings", analysis.at("findings").size()},
          {"available_findings", available},
          {"supported_hidden_available", hidden_available},
          {"groups", groups},
          {"normalization_conflicts", analysis.at("normalization_conflicts").size()},
          {"missing_declared_artifacts",
           analysis.at("missing_declared_artifacts").size()},
          {"measurement_grade", false},
          {"diagnostic_grade", false}};
}

