nlohmann::json DetectionCatalog::Capabilities() {
  nlohmann::json findings = nlohmann::json::array();
  for (const auto& definition : Findings()) findings.push_back(DefinitionJson(definition));
  for (const auto& definition : ExperimentalFindings()) {
    findings.push_back(DefinitionJson(definition));
  }
  const auto hidden = std::count_if(
      Findings().begin(), Findings().end(), [](const DetectionDefinition& definition) {
        return definition.availability == "supported_hidden";
      });
  return {
      {"schema_version", "skin-analysis/capabilities/1.0"},
      {"backends",
       {{"vendor_multispectral_exact",
         {{"required_modalities", {"RGB_M/L/R", "CP_M/L/R", "365_M/L/R"}},
          {"optional_modalities", {"PP_M/L/R"}},
          {"finding_count", Findings().size()},
          {"vendor_equivalent", true}}},
        {"rgb_visual_approximation",
         {{"required_modalities", {"RGB_M"}},
          {"outputs", {"RED", "BROWN", "REDNE", "candidate_redness",
                        "candidate_pigmentation", "confidence"}},
          {"vendor_equivalent", false},
          {"trend_eligible", false}}}}},
      {"counts",
       {{"canonical_findings", Findings().size()},
        {"supported_hidden", hidden},
        {"experimental_unverified", ExperimentalFindings().size()}}},
      {"findings", findings},
      {"measurement_grade", false},
      {"diagnostic_grade", false},
  };
}

